    float thread_sum = 0.0f;
    for (int i = static_cast<int>(threadIdx.x); i < partial_count; i += 256)
        thread_sum += partials[i];

    const float total = BlockReduce(temp_storage).Sum(thread_sum);
    if (threadIdx.x == 0)
        output[0] = total;
}

